// ── framer/shared/month.ts ──────────────────────────────────────────────────

// month.ts — the logic behind the public calendar: which month, which days, which
// classes on each day, the phone's list of upcoming classes, places left and the
// waiting-list link, and each class's shade of the site's colour.
//
// No screen and no network here, so the tests can load it directly.
// Every date and time is worked out in the calendar's timezone, never the visitor's.

interface CalendarSession {    // one class, as the website reads it from Supabase
  id: string
  title: string
  starts_at: string
  ends_at: string
  location: string | null
  details: Record<string, string>
  places_left: number | null          // null = no limit
}

type DayKey = string           // a date in the calendar's timezone, like "2026-09-28"

interface PlacedSession extends CalendarSession {
  day: DayKey                         // its date on the calendar's clock
  time: string                        // start time on the calendar's clock, like "4:30 PM"
  past: boolean                       // started already, so greyed out
}

interface Day {
  key: DayKey
  date: number                        // day of the month
  inMonth: boolean                    // false for the grid's days before the 1st or after the last: left blank
  isToday: boolean
  isPast: boolean                     // the whole day is over, so greyed out
  sessions: PlacedSession[]           // in time order
}

interface Month {
  year: number
  month: number                       // 1 = January … 12 = December
  weekdays: number[]                  // the columns: 0 = Monday … 6 = Sunday
  weeks: Day[][]                      // the rows, one Day per column
}

// ------------------------------------------------------------------
//  Dates and times in the calendar's timezone
// ------------------------------------------------------------------

const formats = new Map<string, Intl.DateTimeFormat>()

// The calendar's date and clock at a moment: { day: "2026-09-30", hour: 16, minute: "30" }
function clock(moment: Date, timeZone: string) {
  if (!formats.has(timeZone)) {
    formats.set(timeZone, new Intl.DateTimeFormat("en-GB", {
      timeZone, year: "numeric", month: "2-digit", day: "2-digit",
      hour: "2-digit", minute: "2-digit", hourCycle: "h23",
    }))
  }
  const parts: Record<string, string> = {}
  for (const p of formats.get(timeZone)!.formatToParts(moment)) parts[p.type] = p.value
  return { day: `${parts.year}-${parts.month}-${parts.day}`, hour: Number(parts.hour), minute: parts.minute }
}

function calendarDay(moment: Date, timeZone: string): DayKey {
  return clock(moment, timeZone).day
}

// A moment's time on the calendar's clock: timeOf(moment, "Asia/Beirut") is "4:30 PM".
function timeOf(moment: Date, timeZone: string): string {
  const { hour, minute } = clock(moment, timeZone)
  return formatTime(hour, minute)
}

// The 12-hour clock: formatTime(16, "30") is "4:30 PM", formatTime(0, "15") is "12:15 AM".
function formatTime(hour: number, minute: string): string {
  return `${hour % 12 || 12}:${minute} ${hour < 12 ? "AM" : "PM"}`
}

// Counting days on dates alone, with no clock involved, so a clock change
// (Lebanon's happen at midnight) can never shift the answer.
function addDays(day: DayKey, n: number): DayKey {
  const [y, m, d] = day.split("-").map(Number)
  return new Date(Date.UTC(y, m - 1, d + n)).toISOString().slice(0, 10)
}

function weekdayOf(day: DayKey): number {   // 0 = Monday … 6 = Sunday
  const [y, m, d] = day.split("-").map(Number)
  return (new Date(Date.UTC(y, m - 1, d)).getUTCDay() + 6) % 7
}

// Today, and the first and last day of the month we're in.
function monthOf(now: Date, timeZone: string) {
  const today = calendarDay(now, timeZone)
  const [year, month] = today.split("-").map(Number)
  const first = `${today.slice(0, 7)}-01`
  const last = new Date(Date.UTC(year, month, 0)).toISOString().slice(0, 10)   // day 0 of next month
  return { today, year, month, first, last }
}

// What to ask Supabase for: the whole month (the grid) and the next 30 days (the phone
// list), plus a day on each side, because the calendar's midnight isn't UTC's.
// buildMonth() and upcoming() then keep exactly the right days.
function fetchRange(now: Date, timeZone: string): { from: DayKey; to: DayKey } {
  const { today, first, last } = monthOf(now, timeZone)
  const listEnd = addDays(today, LIST_DAYS)
  return { from: addDays(first, -1), to: addDays(listEnd > last ? listEnd : last, 2) }
}

// A session with its day, time and state worked out on the calendar's clock.
function place(s: CalendarSession, now: Date, timeZone: string): PlacedSession {
  const start = new Date(s.starts_at)
  const { day, hour, minute } = clock(start, timeZone)
  return { ...s, day, time: formatTime(hour, minute), past: start.getTime() <= now.getTime() }   // greyed from the moment it starts
}

const byStart = (a: PlacedSession, b: PlacedSession) =>
  Date.parse(a.starts_at) - Date.parse(b.starts_at) || a.title.localeCompare(b.title)

// ------------------------------------------------------------------
//  The grid
// ------------------------------------------------------------------

// The month as rows of weeks, Monday to Sunday, with the days before the 1st and after
// the last left blank. `days` is the client's setting (0 = Monday … 6 = Sunday); a day
// that is switched off still gets its column if it has a class this month, so a one-off
// Sunday workshop can't be invisible.
function buildMonth(
  sessions: CalendarSession[],
  { now, timeZone, days }: { now: Date; timeZone: string; days: number[] },
): Month {
  const { today, year, month, first, last } = monthOf(now, timeZone)

  // Every day from the Monday before the 1st to the Sunday after the last.
  const grid: Day[] = []
  const end = addDays(last, 6 - weekdayOf(last))
  for (let key = addDays(first, -weekdayOf(first)); key <= end; key = addDays(key, 1)) {
    const inMonth = key >= first && key <= last
    grid.push({ key, date: Number(key.slice(8)), inMonth, isToday: key === today, isPast: key < today, sessions: [] })
  }

  for (const s of sessions) {
    const placed = place(s, now, timeZone)
    const cell = grid.find((d) => d.key === placed.day && d.inMonth)
    if (cell) cell.sessions.push(placed)                   // else it belongs to another month
  }
  for (const d of grid) d.sessions.sort(byStart)

  // Columns: the chosen days, plus any day of the week that has a class this month.
  const weekdays = [0, 1, 2, 3, 4, 5, 6].filter((w) =>
    days.includes(w) || grid.some((d, i) => i % 7 === w && d.sessions.length > 0))

  // Rows: one per week, keeping only those columns. A row with no day of this month is dropped.
  const weeks: Day[][] = []
  for (let i = 0; i < grid.length; i += 7) {
    const row = weekdays.map((w) => grid[i + w])
    if (row.some((d) => d.inMonth)) weeks.push(row)
  }

  return { year, month, weekdays, weeks }
}

// ------------------------------------------------------------------
//  The phone list
// ------------------------------------------------------------------

const LIST_DAYS = 30          // the phone list runs from today to 30 days ahead

// The phone view: classes that haven't started yet, from now to 30 days ahead, in time
// order, whatever month they're in. Full classes stay in; the page marks them.
function upcoming(sessions: CalendarSession[], { now, timeZone }: { now: Date; timeZone: string }): PlacedSession[] {
  const lastDay = addDays(calendarDay(now, timeZone), LIST_DAYS)
  return sessions
    .map((s) => place(s, now, timeZone))
    .filter((s) => !s.past && s.day <= lastDay)
    .sort(byStart)
}

// ------------------------------------------------------------------
//  Places left and the waiting list
// ------------------------------------------------------------------

// What a class shows about its places: "full", the number when only a few are left, or
// nothing. `showFrom` is the client's setting: 3 shows "3 places left" and fewer; 0 never
// shows a number, only "full".
function placesNote(placesLeft: number | null, showFrom: number): "full" | number | null {
  if (placesLeft === null) return null                  // no limit
  if (placesLeft <= 0) return "full"
  return placesLeft <= showFrom ? placesLeft : null
}

// Puts values into the client's wording: fillIn("See you {day}", { day: "Wed" }) is
// "See you Wed". A name with no value is left as it is.
function fillIn(template: string, values: Record<string, string>): string {
  return template.replace(/\{(\w+)\}/g, (whole, name: string) => values[name] ?? whole)
}

// A link that opens WhatsApp with the message ready to send; null when no number is set.
function whatsappLink(number: string, message: string): string | null {
  const digits = number.replace(/\D/g, "")
  return digits ? `https://wa.me/${digits}?text=${encodeURIComponent(message)}` : null
}

// ------------------------------------------------------------------
//  Names, in the site's language
// ------------------------------------------------------------------

// A row's date in the phone list: "Tue, Sep 29" in English, "mar. 29 sept." in French.
function dayLabel(day: DayKey, language: string): string {
  const [y, m, d] = day.split("-").map(Number)
  return new Intl.DateTimeFormat(language, { weekday: "short", day: "numeric", month: "short", timeZone: "UTC" })
    .format(Date.UTC(y, m - 1, d))
}

// Short day names, Monday first: ["Mon", "Tue", …] in English, ["lun.", "mar.", …] in French.
function weekdayNames(language: string): string[] {
  const format = new Intl.DateTimeFormat(language, { weekday: "short", timeZone: "UTC" })
  return [0, 1, 2, 3, 4, 5, 6].map((i) => format.format(Date.UTC(2026, 8, 28 + i)))   // 28 Sep 2026 was a Monday
}

// The month's title: "September 2026", or "septembre 2026" in French.
function monthTitle(year: number, month: number, language: string): string {
  return new Intl.DateTimeFormat(language, { month: "long", year: "numeric", timeZone: "UTC" })
    .format(Date.UTC(year, month - 1, 1))
}

// ------------------------------------------------------------------
//  Colour: each class name gets a tint of the site's main colour
// ------------------------------------------------------------------

const SHADES = 5              // how many tints; with more class names than this, some share
const LIGHTEST = 0.12         // how much of the main colour is in the lightest tint (the rest is white)
const DEEPEST = 0.55          // ...and in the deepest, unless that would make text hard to read
const MIN_LUMINANCE = 0.45    // lighter than this, dark text on the card stays easy to read

// The class's tint of the main colour: the same name always gets the same tint.
function shadeFor(title: string, mainColour: string): string {
  const main = parseColour(mainColour) ?? [136, 136, 136]   // unreadable setting: grey

  // A very dark main colour can't go as deep, or text on it gets hard to read.
  let deepest = DEEPEST
  while (deepest > LIGHTEST && luminance(tint(main, deepest)) < MIN_LUMINANCE) deepest -= 0.01

  const step = hash(title.trim().toLowerCase()) % SHADES
  const [r, g, b] = tint(main, LIGHTEST + ((deepest - LIGHTEST) * step) / (SHADES - 1))
  return `rgb(${r}, ${g}, ${b})`
}

// Mix a colour with white. share 0 = white, 1 = the colour itself.
function tint(colour: number[], share: number): number[] {
  return colour.map((c) => Math.round(255 - (255 - c) * share))
}

// How light a colour looks, from 0 (black) to 1 (white). The formula accessibility checks use.
function luminance(colour: number[]): number {
  const [r, g, b] = colour.map((c) => {
    const s = c / 255
    return s <= 0.04045 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4
  })
  return 0.2126 * r + 0.7152 * g + 0.0722 * b
}

// The colour itself if text in it is readable on `background` (4.5:1, the accessibility
// minimum), otherwise the colour darkened step by step until it is. For a light main
// colour used as text.
function readableText(colour: string, background: string): string {
  const fg = parseColour(colour)
  const bg = parseColour(background) ?? [255, 255, 255]
  if (!fg) return colour
  const contrast = (c: number[]) => (luminance(bg) + 0.05) / (luminance(c) + 0.05)
  let c = fg
  for (let k = 1; contrast(c) < 4.5 && k <= 20; k++) c = fg.map((v) => Math.round(v * (1 - k * 0.05)))
  return `rgb(${c[0]}, ${c[1]}, ${c[2]})`
}

// Framer gives colours as "#6b7a3a", "rgb(107, 122, 58)", "hsla(75, 36%, 35%, 0.5)" (when
// the colour has transparency), or, for a colour style, "var(--token-…, rgb(107, 122, 58))".
// Reads the first colour it finds.
function parseColour(value: string): number[] | null {
  const rgb = value.match(/rgba?\(\s*(\d+(?:\.\d+)?)[\s,]+(\d+(?:\.\d+)?)[\s,]+(\d+(?:\.\d+)?)/i)
  if (rgb) return [rgb[1], rgb[2], rgb[3]].map((c) => Math.round(Number(c)))

  const hsl = value.match(/hsla?\(\s*(-?\d+(?:\.\d+)?)(?:deg)?[\s,]+(\d+(?:\.\d+)?)%[\s,]+(\d+(?:\.\d+)?)%/i)
  if (hsl) return hslToRgb(Number(hsl[1]), Number(hsl[2]) / 100, Number(hsl[3]) / 100)

  const hex = value.match(/#([0-9a-f]{3}|[0-9a-f]{6}|[0-9a-f]{8})\b/i)
  if (!hex) return null
  const digits = hex[1].length === 3 ? [...hex[1]].map((c) => c + c).join("") : hex[1].slice(0, 6)
  return [0, 2, 4].map((i) => parseInt(digits.slice(i, i + 2), 16))
}

// Hue in degrees, saturation and lightness from 0 to 1, to [red, green, blue] from 0 to 255.
function hslToRgb(hue: number, s: number, l: number): number[] {
  const h = ((hue % 360) + 360) % 360
  const a = s * Math.min(l, 1 - l)
  const channel = (n: number) => {
    const k = (n + h / 30) % 12
    return Math.round(255 * (l - a * Math.max(-1, Math.min(k - 3, 9 - k, 1))))
  }
  return [channel(0), channel(8), channel(4)]
}

// Turns a name into a number, the same on every device (FNV-1a).
function hash(text: string): number {
  let h = 2166136261
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i)
    h = Math.imul(h, 16777619)
  }
  return h >>> 0
}

// ── framer/dashboard/logic.ts ───────────────────────────────────────────────

// logic.ts — what the owner's dashboard works out from owner_sessions(): which
// classes it lists, how full each one is, and what needs the owner's attention.
//
// No screen and no network here, so the tests can load it directly.

interface Booking {
  id: string
  name: string
  phone: string
  created_at: string
  told_at: string | null              // when the owner ticked "told" about a change
}

interface OwnerSession {            // one class, as owner_sessions() returns it
  id: string
  title: string
  starts_at: string
  ends_at: string
  location: string | null
  details: Record<string, string>         // the lines visitors see
  fields: Record<string, string>          // every "Label: value" line, for the filters
  places: number | null                    // null = no limit (or a setup problem)
  problem: string | null                   // set = hidden from the site; the reason
  cancelled_at: string | null              // set = gone from Google Calendar
  moved_from: string | null                // the first time, when Google moved it
  bookings: Booking[]
}

type Attention =
  | { kind: "sync"; lastSync: string | null }        // the calendar hasn't synced lately
  | { kind: "problem"; session: OwnerSession }       // hidden from the site, with the reason
  | { kind: "cancelled"; session: OwnerSession }     // gone from Google; people to tell
  | { kind: "moved"; session: OwnerSession }         // new time; people to tell

const SYNC_LATE = 2.5 * 60 * 60 * 1000     // the timer runs hourly; two missed runs is a problem

// What the owner should look at first. Only classes still to come: once a class is
// over, there's nothing left to do about it, so it drops off on its own.
function needsAttention(sessions: OwnerSession[], lastSync: string | null, now: Date): Attention[] {
  const items: Attention[] = []
  if (!lastSync || now.getTime() - Date.parse(lastSync) > SYNC_LATE) items.push({ kind: "sync", lastSync })

  for (const s of sessions) {
    if (Date.parse(s.starts_at) <= now.getTime()) continue
    if (s.cancelled_at) {
      if (s.bookings.some((b) => !b.told_at)) items.push({ kind: "cancelled", session: s })
    } else if (s.problem) {
      items.push({ kind: "problem", session: s })
    } else if (wasMoved(s) && s.bookings.some((b) => !b.told_at)) {
      items.push({ kind: "moved", session: s })
    }
  }
  return items
}

// Moved back to its first time counts as not moved.
function wasMoved(s: OwnerSession): boolean {
  return s.moved_from !== null && Date.parse(s.moved_from) !== Date.parse(s.starts_at)
}

// The classes the dashboard lists: not cancelled, and not over yet (a class that has
// started stays until it ends, so a walk-in can still be added). In time order.
function ownerClasses(sessions: OwnerSession[], now: Date): OwnerSession[] {
  return sessions
    .filter((s) => !s.cancelled_at && Date.parse(s.ends_at) > now.getTime())
    .sort((a, b) => Date.parse(a.starts_at) - Date.parse(b.starts_at))
}

// How full a class is: "7/10", or "7 booked" when there's no limit.
function fullness(s: OwnerSession): { label: string; full: boolean } {
  const booked = s.bookings.length
  if (s.places === null) return { label: `${booked} booked`, full: false }
  return { label: `${booked}/${s.places}`, full: booked >= s.places }
}

// A number as WhatsApp needs it, with the country code. "+961 70…" and "00961 70…" are
// already international; "70 123 456" or "03 123 456" gets the client's country code,
// without the leading 0. With no country code set, the number is left as it is.
function internationalPhone(phone: string, countryCode: string): string {
  const trimmed = phone.trim()
  const code = countryCode.replace(/\D/g, "")
  if (trimmed.startsWith("+")) return trimmed
  if (trimmed.startsWith("00")) return `+${trimmed.slice(2)}`
  if (!code) return trimmed
  return `+${code}${trimmed.replace(/\D/g, "").replace(/^0+/, "")}`
}

// The owner's search: a class name, a description value ("camila"), a person's name,
// or (3+ digits) part of a phone number, however it's typed: "70123", "+961 70 123" and
// "070 123" all find 70 123 456. Capitals and accents don't matter. Each match lists the
// people who matched, so the list can name them under the class.
function findClasses(sessions: OwnerSession[], query: string, countryCode = ""): { session: OwnerSession; people: Booking[] }[] {
  const text = plain(query)
  if (!text) return []
  const code = countryCode.replace(/\D/g, "")
  const digits = query.replace(/\D/g, "").replace(/^0+/, "")
  const asked = digits.length >= 3 ? phoneForms(digits, code) : []
  const matches: { session: OwnerSession; people: Booking[] }[] = []
  for (const s of sessions) {
    const people = s.bookings.filter((b) => {
      if (plain(b.name).includes(text)) return true
      const stored = [
        ...phoneForms(b.phone.replace(/\D/g, "").replace(/^0+/, ""), code),
        internationalPhone(b.phone, code).replace(/\D/g, ""),
      ]
      return asked.some((a) => stored.some((p) => p.includes(a)))
    })
    const described = Object.values(s.fields ?? {}).some((v) => plain(v).includes(text))
    if (people.length > 0 || plain(s.title).includes(text) || described) matches.push({ session: s, people })
  }
  return matches
}

// A number's digits as written, and without the local 0 after the country code
// ("96103123456" → also "9613123456"), so both ways of writing it match.
function phoneForms(digits: string, code: string): string[] {
  if (!code || !digits.startsWith(code)) return [digits]
  return [digits, code + digits.slice(code.length).replace(/^0+/, "")]
}

// "  Joëlle  HADDAD " → "joelle haddad"
function plain(text: string): string {
  return text.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim().replace(/\s+/g, " ")
}

// A way to narrow the class list: the location, or any "Label: value" line written in
// the class descriptions (Instructor, Level, Room…), so the client decides what can be
// filtered just by writing it in Google Calendar. Labels match whatever their capitals.
// Only offered when it has 2+ values, so it actually narrows something.
interface Filter { key: string; label: string; values: string[] }

function filterOptions(sessions: OwnerSession[]): Filter[] {
  const keys = [{ key: "location", label: "Location" }]
  for (const s of sessions)
    for (const label of Object.keys(s.fields ?? {}))
      if (!keys.some((k) => k.key === `field:${label.toLowerCase()}`)) keys.push({ key: `field:${label.toLowerCase()}`, label })
  return keys
    .map(({ key, label }) => ({
      key, label,
      values: [...new Set(sessions.map((s) => valueOf(s, key)).filter((v): v is string => !!v))].sort(),
    }))
    .filter((f) => f.values.length >= 2)
}

// The classes that match every chosen filter. chosen: { "field:instructor": "Camila M." }
function applyFilters(sessions: OwnerSession[], chosen: Record<string, string>): OwnerSession[] {
  const active = Object.entries(chosen).filter(([, value]) => value)
  return sessions.filter((s) => active.every(([key, value]) => valueOf(s, key) === value))
}

function valueOf(s: OwnerSession, key: string): string | null {
  if (key === "location") return s.location
  const wanted = key.slice("field:".length)
  const label = Object.keys(s.fields ?? {}).find((l) => l.toLowerCase() === wanted)
  return label ? s.fields[label] : null
}

// "+96170123456" → "+961 70 123 456": the client's country code, then the rest in threes
// from the end. Other countries' numbers are shown as typed.
function readablePhone(phone: string, countryCode: string): string {
  const code = countryCode.replace(/\D/g, "")
  const full = internationalPhone(phone, code)
  if (!code || !full.startsWith(`+${code}`)) return phone.trim()
  const rest = full.slice(code.length + 1).replace(/\D/g, "")
  const groups = rest.match(/\d{1,3}(?=(\d{3})*$)/g) ?? [rest]
  return `+${code} ${groups.join(" ")}`
}

// Where someone from a cancelled class was booked instead: the same phone number on
// another class still to come (the earliest, if several). null when they weren't.
function rebookedOn(b: Booking, cancelled: OwnerSession, sessions: OwnerSession[], now: Date): OwnerSession | null {
  const digits = b.phone.replace(/\D/g, "")
  return sessions
    .filter((o) => o.id !== cancelled.id && !o.cancelled_at && Date.parse(o.starts_at) > now.getTime()
      && o.bookings.some((x) => x.phone.replace(/\D/g, "") === digits))
    .sort((x, y) => Date.parse(x.starts_at) - Date.parse(y.starts_at))[0] ?? null
}

// What to do about a class hidden by a setup problem, in the owner's words. The sync
// writes the reason; this turns it into the fix, with the client's own label.
function fixHint(problem: string): string {
  const missing = problem.match(/^No "(.+)" line in the description/)
  if (missing) return `Add a line like "${missing[1]}: 10" to the event's description in Google Calendar.`
  const notNumber = problem.match(/^"(.+)" says ".*", which isn't a number/)
  if (notNumber) return `Write a number on the "${notNumber[1]}" line, like "${notNumber[1]}: 10", in Google Calendar.`
  if (problem.startsWith("No number of places set")) return "Ask your website team to set a number of places for this calendar."
  return "Fix it in Google Calendar."
}

// The class the owner is about to teach: today, not over, not cancelled or hidden. The
// first one under way, else the next to start. null when today's classes are done.
// dayOf: the calendar day a time falls on, in the studio's time zone.
function nextClass(sessions: OwnerSession[], now: Date, today: string, dayOf: (iso: string) => string): OwnerSession | null {
  return ownerClasses(sessions, now).find((s) => !s.problem && dayOf(s.starts_at) === today) ?? null
}

// "in 25 min", "in 2 h", or null once it has started.
function startsIn(startsAt: string, now: Date): string | null {
  const minutes = Math.ceil((Date.parse(startsAt) - now.getTime()) / 60_000)
  if (minutes <= 0) return null
  return minutes < 60 ? `in ${minutes} min` : `in ${Math.round(minutes / 60)} h`
}

// Classes someone could be moved or booked onto: still to come, on the site (not cancelled
// or hidden), with a free place, and not the one they're leaving or one they're already on.
function classesToMoveTo(b: Booking, from: OwnerSession, sessions: OwnerSession[], now: Date): OwnerSession[] {
  const digits = b.phone.replace(/\D/g, "")
  return sessions.filter((o) =>
    o.id !== from.id && !o.cancelled_at && !o.problem && Date.parse(o.starts_at) > now.getTime()
    && (o.places === null || o.bookings.length < o.places)
    && !o.bookings.some((x) => x.phone.replace(/\D/g, "") === digits))
}

// ── framer/dashboard/types.ts ───────────────────────────────────────────────

// types.ts — the dashboard's shared shapes: its settings (Props), the login, the loaded
// data, where the owner is, and how far ahead it looks.

interface Props {
  supabaseUrl: string
  publicKey: string
  studioName: string
  rememberDays: number
  layout: "desktop" | "phone"
  language: string
  mainColour: string
  textColour: string
  mutedColour: string
  lineColour: string
  cardColour: string
  buttonColour: string
  buttonTextColour: string
  dangerColour: string
  countryCode: string
  warningColour: string
  titleFont: CSSProperties
  textFont: CSSProperties
  style?: CSSProperties
}

// expires_at: when Supabase's token runs out (it's refreshed); rememberUntil: when this
// device stops being remembered (null = only until the browser closes). Both in seconds.
type Auth = { access_token: string; refresh_token: string; expires_at: number; rememberUntil: number | null }

type Data = { timeZone: string; lastSync: string | null; sessions: OwnerSession[] }

type Screen = "checking" | "login" | "loading" | "ready" | "not_owner" | "error"

// Where the owner is: a section, and the class open in it (if any).
type Route = { section: "classes" | "attention"; id: string | null }

const BOARD_DAYS = 7          // the class list: today and the next 6 days

const LOOK_AHEAD = 32        // needs attention: the whole month the sync keeps

type Call = <T>(name: string, args: Record<string, unknown>) => Promise<T>

type When = (iso: string) => string

// Shows the ✓ toast. link: one thing to do next, e.g. "Tell Sara" opening WhatsApp.
type ToastLink = { label: string; href: string }
type Notify = (text: string, link?: ToastLink) => void

// ── framer/dashboard/helpers.ts ─────────────────────────────────────────────

// helpers.ts — small helpers the screens share: the address of each section, "3 min
// ago", first names, the language, and what to say when the database refuses something.

function readRoute(hash: string): Route {
  const [key, id] = hash.replace(/^#/, "").split("=")
  if (key === "attention") return { section: "attention", id: id ? decodeURIComponent(id) : null }
  if (key === "class" && id) return { section: "classes", id: decodeURIComponent(id) }
  return { section: "classes", id: null }
}

function writeRoute(route: Route): string {
  if (route.section === "attention") return route.id ? `attention=${encodeURIComponent(route.id)}` : "attention"
  return route.id ? `class=${encodeURIComponent(route.id)}` : ""
}

// How long ago the bookings were loaded: "just now", "3 min ago", "1 h ago".
function ago(time: number) {
  const minutes = Math.floor((Date.now() - time) / 60_000)
  return minutes < 1 ? "just now" : minutes < 60 ? `${minutes} min ago` : `${Math.floor(minutes / 60)} h ago`
}

// "Sara Haddad" → "Sara", for buttons that name who they act on.
function firstName(name: string) {
  return name.trim().split(/\s+/)[0] || name
}

// A language the browser doesn't know (a typo in the settings) falls back to English.
function safeLanguage(language: string): string {
  try {
    new Intl.DateTimeFormat(language)
    return language
  } catch {
    return "en"
  }
}

// What to tell the owner when the database refuses an action.
const REFUSALS: Record<string, string> = {
  full: "This class is full. Use Replace to swap someone in.",
  already_booked: "That phone number is already booked on this class.",
  invalid_name: "Please enter a name.",
  invalid_phone: "Please enter a valid phone number.",
  unavailable: "This class can't take bookings (it's cancelled or hidden from the site).",
  not_found: "That booking no longer exists. The list has been refreshed.",
}

