// ── framer/dashboard/parts.tsx ──────────────────────────────────────────────

// parts.tsx — the small building blocks: the login screen, messages, the loading
// placeholder, the "•••" menu, a refusal line, a person's line, the name-and-phone form,
// and the picker for moving someone to another class.

function Centred({ look, children }: { look: Look; children: ReactNode }) {
  return <div style={look.centred}>{children}</div>
}

function Login({ props, look, logIn }: { props: Props; look: Look; logIn: (email: string, password: string, remember: boolean) => Promise<void> }) {
  const [email, setEmail] = useState("")
  const [password, setPassword] = useState("")
  const [remember, setRemember] = useState(true)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const days = Math.max(1, props.rememberDays ?? 30)

  async function submit(e: FormEvent) {
    e.preventDefault()
    setBusy(true)
    setError(null)
    try {
      await logIn(email.trim(), password, remember)
    } catch (err) {
      setError((err as Error).message === "wrong" ? "Wrong email or password." : "Couldn't reach the server. Please try again.")
      setBusy(false)
    }
  }

  return (
    <form onSubmit={submit} className="bd-fade" style={look.loginCard}>
      <div style={{ textAlign: "center", marginBottom: 8 }}>
        <h1 style={{ ...look.title, fontSize: "2.2em" }}>{props.studioName || "Bookings"}</h1>
        <div style={look.muted}>Bookings</div>
      </div>
      <label>
        Email
        <input className="bd-input" type="email" value={email} onChange={(e) => setEmail(e.target.value)} autoComplete="email" required disabled={busy} style={look.input} />
      </label>
      <label>
        Password
        <input className="bd-input" type="password" value={password} onChange={(e) => setPassword(e.target.value)} autoComplete="current-password" required disabled={busy} style={look.input} />
      </label>
      <label style={{ display: "flex", alignItems: "center", gap: 8, cursor: "pointer" }}>
        <input type="checkbox" checked={remember} onChange={(e) => setRemember(e.target.checked)} disabled={busy} style={{ accentColor: props.mainColour, width: 16, height: 16 }} />
        Remember this device for {days} {days === 1 ? "day" : "days"}
      </label>
      {error && <Alert look={look} text={error} />}
      <button className="bd-btn" type="submit" disabled={busy} style={{ ...look.button, width: "100%", padding: "12px 16px" }}>
        {busy ? <><span className="bd-spinner" aria-hidden="true" />Logging in…</> : "Log in"}
      </button>
    </form>
  )
}

function Message({ props, look, text, action, onAction }: { props: Props; look: Look; text: string; action: string; onAction: () => void }) {
  return (
    <div className="bd-fade" style={{ ...look.loginCard, alignItems: "center", textAlign: "center" }}>
      <h1 style={{ ...look.title, fontSize: "2.2em" }}>{props.studioName || "Bookings"}</h1>
      <div>{text}</div>
      <button className="bd-btn" type="button" onClick={onAction} style={look.button}>{action}</button>
    </div>
  )
}

// While the bookings load: the dashboard's shape, softly shimmering.
function Skeleton({ look }: { look: Look }) {
  const bar = (width: number | string, height: number, extra: CSSProperties = {}) => (
    <div className="bd-skeleton" style={{ width, height, ...extra }} />
  )
  const rows = (n: number) => Array.from({ length: n }, (_, i) => <div key={i}>{bar("100%", 52)}</div>)
  if (!look.isDesktop) {
    return (
      <div aria-busy="true" aria-label="Loading" style={{ display: "flex", flexDirection: "column", gap: 12 }}>
        {bar(140, 34)}
        {bar("60%", 36)}
        {rows(5)}
      </div>
    )
  }
  return (
    <div aria-busy="true" aria-label="Loading" style={look.app}>
      <div style={look.sidebar}>
        {bar(120, 34, { marginBottom: 24 })}
        {bar("100%", 40)}
        {bar("100%", 40)}
      </div>
      <div style={look.surface}>
        <div style={{ ...look.listColumn, display: "flex", flexDirection: "column", gap: 10 }}>
          {bar(110, 14)}
          {rows(3)}
          {bar(110, 14, { marginTop: 12 })}
          {rows(2)}
        </div>
        <div style={{ ...look.detailColumn, display: "flex", flexDirection: "column", gap: 12 }}>
          {bar("50%", 34)}
          {bar("70%", 16)}
          {rows(4)}
        </div>
      </div>
    </div>
  )
}

// A small "•••" menu: opens under its button, closes on a tap outside or Escape.
function Menu({ look, children }: { look: Look; children: ReactNode }) {
  const [open, setOpen] = useState(false)
  useEffect(() => {
    if (!open) return
    const close = () => setOpen(false)
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") setOpen(false) }
    document.addEventListener("click", close)
    document.addEventListener("keydown", onKey)
    return () => {
      document.removeEventListener("click", close)
      document.removeEventListener("keydown", onKey)
    }
  }, [open])
  return (
    <div style={{ position: "relative" }} onClick={(e) => e.stopPropagation()}>
      <button className="bd-action" type="button" aria-label="Menu" aria-haspopup="true" aria-expanded={open}
        onClick={() => setOpen(!open)} style={{ ...look.action, minWidth: 44 }}>•••</button>
      {open && <div style={look.menu}>{children}</div>}
    </div>
  )
}

// A refusal or error, said where it happened: the warning icon and one line of text.
function Alert({ look, text }: { look: Look; text: string }) {
  return (
    <div role="alert" style={look.alert}>
      <span style={{ display: "inline-flex", marginTop: 2 }}><WarningIcon colour={look.warningText} /></span>
      <span>{text}</span>
    </div>
  )
}

// message: the WhatsApp text, ready written ("" for an empty chat). Numbers saved without
// a country code (as people often type them) get the studio's, so WhatsApp can open them.
function Person({ booking: b, look, countryCode, message, open, onToggle }: {
  booking: Booking; look: Look; countryCode: string; message: string; open?: boolean; onToggle?: () => void
}) {
  const whatsapp = whatsappLink(internationalPhone(b.phone, countryCode ?? ""), message)
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
      <span style={{ fontWeight: 600, flex: 1, minWidth: 0, overflowWrap: "anywhere" }}>
        {b.name}
        <span style={{ ...look.muted, display: "block", fontWeight: 400, fontVariantNumeric: "tabular-nums" }}>{readablePhone(b.phone, countryCode ?? "")}</span>
      </span>
      {whatsapp && (
        <a className="bd-action" href={whatsapp} target="_blank" rel="noopener noreferrer"
          aria-label={`WhatsApp ${b.name}`} title="WhatsApp" style={look.iconButton}><ChatIcon colour={look.accent} /></a>
      )}
      {onToggle && (
        <button className="bd-action" type="button" aria-label={`More for ${b.name}`} aria-expanded={!!open}
          onClick={onToggle} style={look.iconButton}>•••</button>
      )}
    </div>
  )
}

// Name and phone, for Add and Replace. Labels stay visible while typing; Cancel or Escape
// closes it; the name field is ready to type in.
function NameAndPhone({ look, button, busy, onSubmit, onCancel }: {
  look: Look; button: string; busy: boolean; onSubmit: (name: string, phone: string) => void; onCancel: () => void
}) {
  const [name, setName] = useState("")
  const [phone, setPhone] = useState("")
  const field = { ...look.note, display: "flex", flexDirection: "column", gap: 4, flex: "1 1 160px", minWidth: 0 } as CSSProperties
  return (
    <form
      onSubmit={(e) => { e.preventDefault(); onSubmit(name.trim(), phone) }}
      onKeyDown={(e) => { if (e.key === "Escape") onCancel() }}
      style={{ display: "flex", flexWrap: "wrap", gap: 8, alignItems: "flex-end", marginTop: 8 }}
    >
      <label style={field}>
        Name
        <input className="bd-input" autoFocus value={name} onChange={(e) => setName(e.target.value)}
          required maxLength={80} autoComplete="off" style={{ ...look.input, marginTop: 0 }} />
      </label>
      <label style={field}>
        Phone
        <input className="bd-input" type="tel" inputMode="tel" value={phone} onChange={(e) => setPhone(e.target.value)}
          required autoComplete="off" style={{ ...look.input, marginTop: 0 }} />
      </label>
      <div style={{ display: "flex", gap: 8 }}>
        <button className="bd-btn" type="submit" disabled={busy} style={look.button}>
          {busy ? <><span className="bd-spinner" aria-hidden="true" />{button}…</> : button}
        </button>
        <button className="bd-action" type="button" onClick={onCancel} disabled={busy} style={look.action}>Cancel</button>
      </div>
    </form>
  )
}

// Pick another class for someone: for booking people from a cancelled class elsewhere, or
// moving them. Lists the classes they could go to, with the places left.
function ClassPicker({ look, when, choices, title, button, busy, onPick, onCancel }: {
  look: Look; when: (iso: string) => string; choices: OwnerSession[]
  title: string; button: string; busy: boolean; onPick: (to: OwnerSession) => void; onCancel: () => void
}) {
  const [target, setTarget] = useState("")
  const picked = choices.find((o) => o.id === target)
  return (
    <div style={look.picker} onKeyDown={(e) => { if (e.key === "Escape") onCancel() }}>
      <label style={{ display: "flex", flexDirection: "column", gap: 4 }}>
        <strong>{title}</strong>
        <select className="bd-input" value={target} onChange={(e) => setTarget(e.target.value)} autoFocus
          style={{ ...look.input, marginTop: 0 }}>
          <option value="">Pick a class</option>
          {choices.map((o) => (
            <option key={o.id} value={o.id}>
              {o.title} · {when(o.starts_at)}{o.places !== null && ` · ${o.places - o.bookings.length} left`}
            </option>
          ))}
        </select>
      </label>
      <div style={look.actions}>
        <button className="bd-btn" type="button" disabled={!picked || busy} onClick={() => picked && onPick(picked)} style={look.button}>
          {busy ? <><span className="bd-spinner" aria-hidden="true" />{button}…</> : button}
        </button>
        <button className="bd-action" type="button" onClick={onCancel} disabled={busy} style={look.action}>Cancel</button>
      </div>
    </div>
  )
}

// ── framer/dashboard/Attention.tsx ──────────────────────────────────────────

// Attention.tsx — Needs attention: classes hidden by a setup problem, and cancelled or
// moved classes with people to tell. Ready-written WhatsApp messages, Told ticks, booking
// people from a cancelled class on another one, and moving people who can't make a new
// time. Also the late-sync banner.

const KINDS: { kind: Attention["kind"]; title: string }[] = [
  { kind: "problem", title: "Hidden from the site" },
  { kind: "cancelled", title: "Cancelled — people to tell" },
  { kind: "moved", title: "Moved — people to tell" },
]

function AttentionList({ attention, look, when, selected, pick }: {
  attention: Attention[]; look: Look; when: When; selected: string | null; pick: (id: string) => void
}) {
  // A late sync shows as the banner above every section, so it isn't repeated here.
  const classes = attention.filter((a) => a.kind !== "sync")
  if (classes.length === 0) return <p style={look.muted}>{attention.length ? "Nothing else needs your attention." : "All clear. Cancelled, moved, or hidden classes will show up here."}</p>
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
      {KINDS.map(({ kind, title }) => {
        const items = attention.filter((a) => a.kind === kind)
        if (items.length === 0) return null
        return (
          <div key={kind} style={{ display: "flex", flexDirection: "column", gap: 6 }}>
            <h3 style={look.heading}>{title} · {items.length}</h3>
            {items.map((a) => {
              if (a.kind === "sync") return null
              const s = a.session
              return (
                <button className="bd-row" key={s.id} type="button" onClick={() => pick(s.id)} aria-current={s.id === selected ? "true" : undefined} style={look.item(s.id === selected)}>
                  {a.kind === "moved" ? <ClockIcon colour={look.mutedColour} /> : <WarningIcon colour={look.warningText} />}
                  <span style={{ flex: 1, minWidth: 0 }}>
                    <span style={{ fontWeight: 600 }}>{s.title}</span>
                    <span style={look.note}>{when(s.starts_at)}</span>
                  </span>
                  {a.kind !== "problem" && <span style={{ whiteSpace: "nowrap" }}>{s.bookings.filter((b) => !b.told_at).length} to tell</span>}
                  <span aria-hidden="true" style={look.muted}>›</span>
                </button>
              )
            })}
          </div>
        )
      })}
    </div>
  )
}

function AttentionDetail({ item, look, when, call, reload, sessions, studio, countryCode, notify }: {
  item: Exclude<Attention, { kind: "sync" }>; look: Look; when: When; call: Call; reload: () => Promise<unknown>
  sessions: OwnerSession[]; studio: string; countryCode: string; notify: Notify
}) {
  const toldHeading = useRef<HTMLHeadingElement>(null)          // where focus goes after an action
  const s = item.session
  const [busy, setBusy] = useState<string | null>(null)                 // the booking being saved
  const [moving, setMoving] = useState<string | null>(null)             // the booking being put on another class
  const [notice, setNotice] = useState<{ at: string; text: string } | null>(null)
  const told = s.bookings.filter((b) => b.told_at).length
  const text =
    item.kind === "problem" ? `Hidden from the site: ${s.problem}. ${fixHint(s.problem!)} It reappears at the next sync.`
    : item.kind === "cancelled" ? "Cancelled in Google Calendar. Let these people know, then tick them off:"
    : `Moved from ${when(s.moved_from!)} to ${when(s.starts_at)}. Let these people know, then tick them off:`

  async function save(b: Booking, work: () => Promise<string | null>, success: string, link?: ToastLink) {
    setBusy(b.id)
    setNotice(null)
    try {
      const problem = await work()
      setBusy(null)
      if (problem) setNotice({ at: b.id, text: problem })
      else {
        setMoving(null)
        notify(success, link)
      }
      await reload()
      if (!problem) toldHeading.current?.focus()
    } catch {
      setNotice({ at: b.id, text: "That didn't go through. Please try again." })
      setBusy(null)
    }
  }

  const markTold = (b: Booking, value: boolean) => save(b, async () => {
    const answer = await call<{ status: string }>("owner_mark_told", { p_booking: b.id, p_told: value })
    return REFUSALS[answer.status] ?? null
  }, value ? `${b.name} ticked as told` : `${b.name} unticked`)

  // Book them on the other class. Told stays unticked: they still need telling, and their
  // WhatsApp message now says where they've been booked.
  const bookElsewhere = (b: Booking, other: OwnerSession) => save(b, async () => {
    const answer = await call<{ status: string }>("owner_add", { p_session: other.id, p_name: b.name, p_phone: b.phone })
    return REFUSALS[answer.status] ?? null
  }, `${b.name} booked on ${other.title}, ${when(other.starts_at)} · now tell ${firstName(b.name)}`)

  // Can't make the new time: move them to another class in one step (booked there, their
  // place here freed). They leave this list, so the toast offers to tell them.
  const moveTo = (b: Booking, to: OwnerSession) => {
    const whatsapp = whatsappLink(internationalPhone(b.phone, countryCode ?? ""), moveMessage(b, s, to, when, studio))
    return save(b, async () => {
      const answer = await call<{ status: string }>("owner_move", { p_booking: b.id, p_session: to.id })
      return answer.status === "full" ? "That class just filled up. Pick another one." : REFUSALS[answer.status] ?? null
    }, `${b.name} moved to ${to.title}, ${when(to.starts_at)}`, whatsapp ? { label: `Tell ${firstName(b.name)}`, href: whatsapp } : undefined)
  }

  // Everyone at once. A WhatsApp link opens one chat, so "everyone" is a message to copy
  // (for a broadcast list or a group) and one button to tick all who are left.
  const [copied, setCopied] = useState(false)
  const untold = s.bookings.filter((b) => !b.told_at)
  async function copyForEveryone() {
    try {
      await navigator.clipboard.writeText(changeMessage(item, null, when, studio, null))
      setCopied(true)
      window.setTimeout(() => setCopied(false), 3000)
    } catch {
      notify("Couldn't copy here. Open one person's WhatsApp and copy the message from there.")
    }
  }
  async function markAll() {
    setBusy("all")
    setNotice(null)
    const results = await Promise.allSettled(untold.map((b) => call("owner_mark_told", { p_booking: b.id, p_told: true })))
    const failed = results.filter((r) => r.status === "rejected").length
    setBusy(null)
    notify(failed ? `${untold.length - failed} ticked as told; ${failed} didn't go through. Please try again.` : "Everyone ticked as told")
    await reload()
    toldHeading.current?.focus()
  }

  return (
    <div className="bd-fade" style={{ display: "flex", flexDirection: "column", gap: 20 }}>
      <div>
        <h2 style={{ ...look.title, fontSize: "1.8em" }}>{s.title}</h2>
        <div style={{ ...look.muted, marginTop: 4 }}>{when(s.starts_at)}</div>
      </div>
      <div style={item.kind === "moved" ? look.softPanel : look.warningPanel}>
        {item.kind === "moved" ? <ClockIcon colour={look.mutedColour} /> : <WarningIcon colour={look.warningText} />}
        <span>{text}</span>
      </div>
      {item.kind !== "problem" && (
        <div style={{ display: "flex", flexDirection: "column" }}>
          <h3 ref={toldHeading} tabIndex={-1} style={{ ...look.heading, marginBottom: 4, outline: "none" }}>
            {told === s.bookings.length ? `Everyone's been told · ${told}` : `Told ${told} of ${s.bookings.length}`}
          </h3>
          {s.bookings.length > 1 && (
            <div style={{ ...look.actions, marginTop: 4, marginBottom: 12 }}>
              <button className="bd-action" type="button" onClick={() => void copyForEveryone()} style={look.action}>
                {copied ? "Copied ✓" : "Copy message for everyone"}
              </button>
              {untold.length > 1 && (
                <button className="bd-action" type="button" disabled={busy !== null} onClick={() => void markAll()} style={look.action}>
                  {busy === "all" ? <><span className="bd-spinner" aria-hidden="true" />Marking…</> : `Mark all ${untold.length} as told`}
                </button>
              )}
            </div>
          )}
          {s.bookings.map((b) => {
            const moved = item.kind === "cancelled" ? rebookedOn(b, s, sessions, new Date()) : null
            const choices = moved ? [] : classesToMoveTo(b, s, sessions, new Date())
            const first = firstName(b.name)
            return (
              <div key={b.id} style={{ borderTop: `1px solid ${look.line}`, padding: "12px 0" }}>
                <Person booking={b} look={look} countryCode={countryCode} message={changeMessage(item, b, when, studio, moved)} />
                {moved && <div style={look.note}>Booked on {moved.title} · {when(moved.starts_at)}</div>}
                <div style={look.actions}>
                  <button className="bd-action" type="button" disabled={busy !== null} aria-pressed={!!b.told_at}
                    onClick={() => void markTold(b, !b.told_at)} style={look.action}>
                    {b.told_at ? <>Told<span aria-hidden="true"> ✓</span></> : "Mark as told"}
                  </button>
                  {choices.length > 0 && moving !== b.id && (
                    <button className="bd-link" type="button" disabled={busy !== null}
                      onClick={() => setMoving(b.id)} style={look.link}>
                      {item.kind === "cancelled" ? "Book on another class…" : "Can't make it? Move to another class…"}
                    </button>
                  )}
                </div>
                {moving === b.id && (
                  <ClassPicker look={look} when={when} choices={choices} busy={busy === b.id} onCancel={() => setMoving(null)}
                    {...(item.kind === "cancelled"
                      ? { title: `Book ${first} on:`, button: `Book ${first}`, onPick: (to: OwnerSession) => void bookElsewhere(b, to) }
                      : { title: `Move ${first} to:`, button: `Move ${first}`, onPick: (to: OwnerSession) => void moveTo(b, to) })} />
                )}
                {notice?.at === b.id && <Alert look={look} text={notice.text} />}
              </div>
            )
          })}
        </div>
      )}
    </div>
  )
}

// The WhatsApp message for someone on a cancelled or moved class, ready to send.
// The WhatsApp message after moving someone to another class.
function moveMessage(b: Booking, from: OwnerSession, to: OwnerSession, when: When, studio: string) {
  const at = (iso: string) => when(iso).replace(" · ", " at ")
  return `Hi ${firstName(b.name)}, it's ${studio}. No problem, we've moved you from ${from.title} to ${to.title}, ${at(to.starts_at)}. See you there!`
}

// b: the person, or null for the copy that goes to everyone ("Hi, it's Neroli.").
// moved: the class they were booked on instead, if any.
function changeMessage(item: Exclude<Attention, { kind: "sync" }>, b: Booking | null, when: When, studio: string, moved: OwnerSession | null) {
  const at = (iso: string) => when(iso).replace(" · ", " at ")
  const s = item.session
  const hello = b ? `Hi ${firstName(b.name)}, it's ${studio}.` : `Hi, it's ${studio}.`
  return item.kind === "cancelled"
    ? `${hello} Sorry, ${s.title} on ${at(s.starts_at)} is cancelled. ` + (moved
      ? `We've booked you on ${moved.title}, ${at(moved.starts_at)} instead. Reply here if that doesn't work for you.`
      : "Reply here and we'll find you another class.")
    : `${hello} ${s.title} has moved from ${at(s.moved_from!)} to ${at(s.starts_at)}. Does the new time still work for you?`
}

// A late or missing calendar sync, above every section: it affects the whole site.
function SyncBanner({ item, look, when }: { item: Attention; look: Look; when: When }) {
  if (item.kind !== "sync") return null
  return (
    <div role="status" style={look.warningBanner}>
      <WarningIcon colour={look.warningText} />
      <span>
        <strong>{item.lastSync ? `The calendar hasn't synced since ${when(item.lastSync)}.` : "The calendar has never synced."}</strong>{" "}
        Bookings on the website still work; changes made in Google Calendar won't show until it syncs. If this lasts more than a few hours, contact your website team.
      </span>
    </div>
  )
}

// ── framer/dashboard/ClassDetail.tsx ────────────────────────────────────────

// ClassDetail.tsx — one class: how full it is, + Add someone, and its people, each with
// WhatsApp and (behind "•••") Replace, Move to another class, and Remove, which asks first.

function ClassDetail({ session: s, look, when, call, reload, countryCode, notify, sessions, studio, openAttention, startAdding = false }: {
  session: OwnerSession; look: Look; when: When; call: Call; reload: () => Promise<unknown>; countryCode: string
  notify: Notify; sessions: OwnerSession[]; studio: string
  openAttention: (id: string) => void   // the class's item in Needs attention, where people are told
  startAdding?: boolean            // opened from "+ Walk-in": the Add form is ready
}) {
  const peopleHeading = useRef<HTMLHeadingElement>(null)        // where focus goes after an action
  const [adding, setAdding] = useState(startAdding)
  const [replacing, setReplacing] = useState<string | null>(null)       // the booking being replaced
  const [removing, setRemoving] = useState<string | null>(null)         // the booking being removed
  const [moving, setMoving] = useState<string | null>(null)             // the booking being moved to another class
  const [openRow, setOpenRow] = useState<string | null>(null)           // whose Replace and Remove are showing
  const [busy, setBusy] = useState(false)
  const [notice, setNotice] = useState<{ at: string; text: string } | null>(null)  // a refusal, and which form it belongs to
  const { label, full } = fullness(s)
  const count = (n: number) => (s.places === null ? `${n} booked` : `${n}/${s.places}`)
  const classWhen = when(s.starts_at)
  const untold = s.bookings.filter((b) => !b.told_at).length    // for a moved class: people still to tell
  const started = Date.parse(s.starts_at) <= Date.now()
  // What happens to the freed spot, said at the moment of choosing.
  const spotNote = s.problem ? "The class is hidden from the site, so the spot won't be offered."
    : started ? "The class has started, so the spot won't be offered on the website."
    : "Their spot opens on the website straight away."

  // Moving someone: booked on the other class and their place here freed, in one step.
  // They leave this list, so the toast offers to tell them on WhatsApp.
  const moveChoices = (b: Booking) => classesToMoveTo(b, s, sessions, new Date())
  const moveTo = (b: Booking, to: OwnerSession) => {
    const whatsapp = whatsappLink(internationalPhone(b.phone, countryCode ?? ""), moveMessage(b, s, to, when, studio))
    return act(b.id, "owner_move", { p_booking: b.id, p_session: to.id }, `${b.name} moved to ${to.title}, ${when(to.starts_at)}`,
      whatsapp ? { label: `Tell ${firstName(b.name)}`, href: whatsapp } : undefined,
      { full: "That class just filled up. Pick another one." })
  }

  // One action: ask the database. A refusal is explained under the form it came from; a
  // success is confirmed for 5 seconds. Then everything is loaded again, with the buttons
  // already free.
  // link: one thing to do next, in the toast. refusals: wording that fits this action better.
  async function act(at: string, name: string, args: Record<string, unknown>, success: string,
    link?: ToastLink, refusals: Record<string, string> = {}) {
    setBusy(true)
    setNotice(null)
    try {
      const answer = await call<{ status: string }>(name, args)
      const problem = refusals[answer.status] ?? REFUSALS[answer.status]
      setBusy(false)
      if (problem) setNotice({ at, text: problem })
      else {
        setAdding(false); setReplacing(null); setRemoving(null); setMoving(null); setOpenRow(null)
        notify(success, link)
      }
      await reload()
      if (!problem) peopleHeading.current?.focus()
    } catch {
      setNotice({ at, text: "That didn't go through. Please try again." })
      setBusy(false)
    }
  }
  const refusal = (at: string) => (notice?.at === at ? <Alert look={look} text={notice.text} /> : null)

  const facts = [Object.values(s.details).join(" · "), s.location].filter(Boolean)

  return (
    <div className="bd-fade" style={{ display: "flex", flexDirection: "column", gap: 20 }}>
      <div>
        <h2 style={{ ...look.title, fontSize: "1.8em" }}>{s.title}</h2>
        <div style={{ ...look.muted, marginTop: 4 }}>{classWhen}{facts.length > 0 && ` · ${facts.join(" · ")}`}</div>
        <div style={{ marginTop: 10, display: "inline-block", ...look.chip(full) }}>
          {full ? `Full · ${label}` : label}
        </div>
        {s.problem && (
          <div style={{ ...look.warningPanel, marginTop: 12 }}>
            <WarningIcon colour={look.warningText} />
            <span><strong>Hidden from the site.</strong> {s.problem}. {fixHint(s.problem)}</span>
          </div>
        )}
        {!s.problem && wasMoved(s) && (
          <div style={{ ...look.softPanel, marginTop: 12 }}>
            <ClockIcon colour={look.mutedColour} />
            <span>
              Moved from {when(s.moved_from!)}.{" "}
              {untold > 0 ? (
                <>
                  {untold === 1 ? "1 person" : `${untold} people`} still to tell.{" "}
                  <button className="bd-link" type="button" onClick={() => openAttention(s.id)} style={look.link}>
                    Open in Needs attention
                  </button>
                </>
              ) : s.bookings.length > 0 ? "Everyone's been told." : null}
            </span>
          </div>
        )}
      </div>

      {/* Adding someone comes first: a walk-in shouldn't need a scroll past everyone booked */}
      {(!s.problem || refusal("add")) && (
        <div style={{ display: "flex", flexDirection: "column" }}>
          {s.problem ? null : full ? (
            <div style={look.muted}>Full — use Replace to swap someone in.</div>
          ) : adding ? (
            <NameAndPhone look={look} button="Add" busy={busy} onCancel={() => setAdding(false)}
              onSubmit={(name, phone) => void act("add", "owner_add", { p_session: s.id, p_name: name, p_phone: phone }, `${name} added · ${count(s.bookings.length + 1)}`)} />
          ) : (
            <button className="bd-btn" type="button" onClick={() => { setAdding(true); setReplacing(null) }} style={{ ...look.button, alignSelf: "flex-start" }}>+ Add someone</button>
          )}
          {refusal("add")}
        </div>
      )}

      <div style={{ display: "flex", flexDirection: "column" }}>
        <h3 ref={peopleHeading} tabIndex={-1} style={{ ...look.heading, marginBottom: 4, outline: "none" }}>People</h3>
        {s.bookings.length === 0 && <div style={{ ...look.muted, padding: "12px 0" }}>
          {s.problem ? "No one booked yet." : "No one booked yet. Bookings from the website appear here, or use + Add someone."}
        </div>}
        {s.bookings.map((b) => (
          <div key={b.id} style={{ borderTop: `1px solid ${look.line}`, padding: "12px 0" }}>
            <Person booking={b} look={look} countryCode={countryCode} message="" open={openRow === b.id}
              onToggle={() => { setOpenRow(openRow === b.id ? null : b.id); setRemoving(null); setReplacing(null); setAdding(false) }} />
            {openRow === b.id && (
              <div style={look.actions} onKeyDown={(e) => { if (e.key === "Escape") setOpenRow(null) }}>
                <button className="bd-action" type="button" disabled={busy} aria-pressed={replacing === b.id}
                  onClick={() => { setReplacing(replacing === b.id ? null : b.id); setRemoving(null); setMoving(null) }}
                  style={look.action}>Replace</button>
                {moveChoices(b).length > 0 && (
                  <button className="bd-action" type="button" disabled={busy} aria-pressed={moving === b.id}
                    onClick={() => { setMoving(moving === b.id ? null : b.id); setRemoving(null); setReplacing(null) }}
                    style={look.action}>Move</button>
                )}
                <button className="bd-action" type="button" disabled={busy}
                  onClick={() => { setRemoving(b.id); setReplacing(null); setMoving(null) }}
                  style={look.action}>Remove</button>
              </div>
            )}

            {removing === b.id && (
              <div role="alertdialog" aria-label={`Remove ${b.name}?`} style={look.confirm}
                onKeyDown={(e) => { if (e.key === "Escape") setRemoving(null) }}>
                <strong>Remove {b.name} from {s.title}, {classWhen}?</strong>
                <span style={look.muted}>{spotNote}</span>
                <div style={look.actions}>
                  <button className="bd-btn" type="button" disabled={busy}
                    onClick={() => void act(b.id, "owner_cancel", { p_booking: b.id },
                      `${b.name} removed · ${s.problem || started ? "the spot isn't offered on the website" : "the spot is open on the website"}`)}
                    style={look.dangerButton}>
                      {busy ? <><span className="bd-spinner" aria-hidden="true" />Removing…</> : `Remove ${firstName(b.name)}`}
                    </button>
                  <button className="bd-action" type="button" autoFocus onClick={() => setRemoving(null)}
                    style={look.action}>Keep booking</button>
                </div>
                {!s.problem && (
                  <button className="bd-link" type="button" onClick={() => { setRemoving(null); setReplacing(b.id) }}
                    style={{ ...look.link, alignSelf: "flex-start" }}>Someone else is taking the spot? Replace instead</button>
                )}
              </div>
            )}

            {moving === b.id && (
              <ClassPicker look={look} when={when} choices={moveChoices(b)} busy={busy} onCancel={() => setMoving(null)}
                title={`Move ${firstName(b.name)} to:`} button={`Move ${firstName(b.name)}`}
                onPick={(to) => void moveTo(b, to)} />
            )}
            {replacing === b.id && (
              <NameAndPhone look={look} button={`Replace ${firstName(b.name)}`} busy={busy} onCancel={() => setReplacing(null)}
                onSubmit={(name, phone) => void act(b.id, "owner_replace", { p_booking: b.id, p_name: name, p_phone: phone }, `${b.name} replaced by ${name}`)} />
            )}
            {refusal(b.id)}
          </div>
        ))}
      </div>

    </div>
  )
}

// ── framer/dashboard/ClassesList.tsx ────────────────────────────────────────

// ClassesList.tsx — the Classes section: one compact row per class, grouped by day.

// people: for search results, who matched in each class, named under its title.
function WeekList({ groups, empty, people, dayName, look, tz, selected, pick }: {
  groups: [string, OwnerSession[]][]; empty: string; people?: Map<string, Booking[]>
  dayName: (day: string) => string; look: Look; tz: string; selected?: string; pick: (id: string) => void
}) {
  if (groups.length === 0) return <p style={look.muted}>{empty}</p>
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
      {groups.map(([day, classes]) => (
        <div key={day} style={{ display: "flex", flexDirection: "column", gap: 6 }}>
          <h3 style={look.heading}>{dayName(day)}</h3>
          {classes.map((s) => {
            const { label, full } = fullness(s)
            return (
              <button className="bd-row" key={s.id} type="button" onClick={() => pick(s.id)} aria-current={s.id === selected ? "true" : undefined} style={look.item(s.id === selected)}>
                <span style={{ minWidth: 70, fontWeight: 600, fontVariantNumeric: "tabular-nums" }}>{timeOf(new Date(s.starts_at), tz)}</span>
                <span style={{ flex: 1, minWidth: 0 }}>
                  {s.title}
                  {people?.get(s.id)?.length ? <span style={look.note}>{people.get(s.id)!.map((b) => b.name).join(", ")}</span> : null}
                  {s.problem &&<span style={look.warningNote}><WarningIcon colour={look.warningText} /> Hidden from the site</span>}
                  {!s.problem && wasMoved(s) && (
                    <span style={{ ...look.note, display: "flex", alignItems: "center", gap: 6 }}>
                      <ClockIcon colour={look.mutedColour} /> Moved from {timeOf(new Date(s.moved_from!), tz)}
                    </span>
                  )}
                </span>
                <span style={{ fontWeight: s.problem ? 400 : 600, color: s.problem ? look.mutedColour : full ? look.accent : undefined, whiteSpace: "nowrap", fontVariantNumeric: "tabular-nums" }}>{full ? `Full · ${label}` : label}</span>
                <span aria-hidden="true" style={look.muted}>›</span>
              </button>
            )
          })}
        </div>
      ))}
    </div>
  )
}

// The Classes section: the search, the filters (folded behind "Filter" on a phone), then
// this week by day, or what the search finds, and the rest of the month on request.
// Board keeps the state, so switching to Needs attention and back keeps the search.
function ClassesList({ look, query, setQuery, filters, chosen, setChosen, showFilters, setShowFilters,
  showLater, setShowLater, found, week, later, byDay, dayName, tz, selected, pick, nextCard }: {
  look: Look; query: string; setQuery: (q: string) => void
  filters: Filter[]; chosen: Record<string, string>; setChosen: (c: Record<string, string>) => void
  showFilters: boolean; setShowFilters: (open: boolean) => void; showLater: boolean; setShowLater: (open: boolean) => void
  found: { session: OwnerSession; people: Booking[] }[] | null
  week: [string, OwnerSession[]][]; later: [string, OwnerSession[]][]; byDay: (list: OwnerSession[]) => [string, OwnerSession[]][]
  dayName: (day: string) => string; tz: string; selected?: string; pick: (id: string) => void
  nextCard?: ReactNode             // the phone's "Next class" card, when there is one
}) {
  const filtering = Object.values(chosen).some(Boolean)
  const laterCount = later.reduce((n, [, classes]) => n + classes.length, 0)
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
      {nextCard}
      {/* On a phone the filters fold behind "Filter", so the first screen shows classes */}
      <div style={{ display: "flex", gap: 8 }}>
        <input className="bd-input" type="search" placeholder="Find a person or class" aria-label="Find a person or class"
          value={query} onChange={(e) => setQuery(e.target.value)} style={{ ...look.input, marginTop: 0, flex: 1, minWidth: 0 }} />
        {!look.isDesktop && filters.length > 0 && (
          <button className="bd-action" type="button" aria-expanded={showFilters} onClick={() => setShowFilters(!showFilters)}
            style={look.filterButton(filtering)}>
            {filtering ? `Filter · ${Object.values(chosen).filter(Boolean).length}` : "Filter"}
          </button>
        )}
      </div>
      {filters.length > 0 && (look.isDesktop || showFilters) && (
        <div style={{ display: "flex", flexWrap: "wrap", gap: 8, alignItems: "flex-end", marginTop: -8 }}>
          {filters.map((f) => (
            <label key={f.key} style={{ ...look.note, display: "flex", flexDirection: "column", gap: 4, flex: "1 1 120px", minWidth: 0 }}>
              {f.label}
              <select className="bd-input" value={chosen[f.key] ?? ""} style={{ ...look.input, marginTop: 0 }}
                onChange={(e) => setChosen({ ...chosen, [f.key]: e.target.value })}>
                <option value="">All</option>
                {f.values.map((v) => <option key={v} value={v}>{v}</option>)}
              </select>
            </label>
          ))}
          {filtering && (
            <button className="bd-link" type="button" onClick={() => setChosen({})} style={{ ...look.link, minHeight: 44 }}>Clear filters</button>
          )}
        </div>
      )}
      {found ? (
        <WeekList groups={byDay(found.map((f) => f.session))} people={new Map(found.map((f) => [f.session.id, f.people]))}
          empty={`No class or person matches "${query.trim()}"${filtering ? " with these filters" : ""}.`}
          dayName={dayName} look={look} tz={tz} selected={selected} pick={pick} />
      ) : (
        <>
          <WeekList groups={week} empty={`${filtering ? "No classes match these filters in the next 7 days." : "No classes in the next 7 days. Classes you add in Google Calendar show up here within the hour."}`}
            dayName={dayName} look={look} tz={tz} selected={selected} pick={pick} />
          {later.length > 0 && (
            <button className="bd-link" type="button" aria-expanded={showLater} onClick={() => setShowLater(!showLater)}
              style={{ ...look.link, alignSelf: "flex-start" }}>
              {showLater ? "Hide later this month" : `Later this month · ${laterCount} ${laterCount === 1 ? "class" : "classes"}`}
            </button>
          )}
          {showLater && <WeekList groups={later} empty="" dayName={dayName} look={look} tz={tz} selected={selected} pick={pick} />}
        </>
      )}
    </div>
  )
}

// The phone's "Next class" card: the class the owner is about to teach (or is teaching),
// how full it is, and a walk-in two taps away.
function NextClassCard({ session: s, look, tz, now, onAdd, onOpen }: {
  session: OwnerSession; look: Look; tz: string; now: Date; onAdd: () => void; onOpen: () => void
}) {
  const { label, full } = fullness(s)
  const soon = startsIn(s.starts_at, now)
  const left = s.places === null ? null : s.places - s.bookings.length
  const status = full ? `Full · ${label}` : left === null ? label : `${label} · ${left} ${left === 1 ? "place" : "places"} left`
  return (
    <section aria-label="Next class" style={look.nextCard}>
      <div style={look.heading}>{soon ? `Next · ${soon}` : `Now · until ${timeOf(new Date(s.ends_at), tz)}`}</div>
      <div style={{ fontWeight: 600, fontSize: "1.1em", marginTop: 6 }}>{s.title} · {timeOf(new Date(s.starts_at), tz)}</div>
      <div style={{ ...look.muted, marginTop: 2, fontVariantNumeric: "tabular-nums" }}>{status}</div>
      <div style={{ ...look.actions, marginTop: 12 }}>
        {full
          ? <button className="bd-action" type="button" onClick={onOpen} style={look.action}>Full · Replace someone</button>
          : <button className="bd-btn" type="button" onClick={onAdd} style={{ ...look.button, minHeight: 44 }}>+ Walk-in</button>}
        <button className="bd-action" type="button" onClick={onOpen} style={look.action}>Who's coming ›</button>
      </div>
    </section>
  )
}

// ── framer/dashboard/Board.tsx ──────────────────────────────────────────────

// Board.tsx — the layout once logged in. On a desktop: a tinted sidebar fixed to the full
// height, then one surface with the list and the details side by side, each scrolling on
// its own. On a phone: one screen at a time, the sections and Refresh in a bar at the
// bottom. Also Refresh (which syncs Google Calendar first) and the ✓ toast.

function Board({ inEditor, data, loadedAt, props, look, call, reload, logOut, route, go }: {
  inEditor: boolean; data: Data; loadedAt: number; props: Props; look: Look; call: Call; reload: () => Promise<Data | null>; logOut: () => void
  route: Route; go: (to: Route) => void
}) {
  const [refreshing, setRefreshing] = useState(false)
  const [slow, setSlow] = useState(false)                  // the sync didn't finish within 20 seconds
  // One confirmation for the whole dashboard ("✓ Sara added · 8/10"), shown where it's
  // always in sight: above the phone's bar, or at the bottom on a desktop. 5 seconds, or 8
  // when it offers something to do next ("Tell Sara").
  const [toast, setToast] = useState<{ text: string; link?: ToastLink } | null>(null)
  const toastTimer = useRef<number | undefined>(undefined)
  const notify: Notify = (text, link) => {
    setToast({ text, link })
    window.clearTimeout(toastTimer.current)
    toastTimer.current = window.setTimeout(() => setToast(null), link ? 8000 : 5000)
  }
  useEffect(() => () => window.clearTimeout(toastTimer.current), [])
  useEffect(() => setSlow(false), [data.lastSync])         // …until a later load brings it in
  const [query, setQuery] = useState("")                  // the search box
  const [showLater, setShowLater] = useState(false)       // "Later this month" opened
  const [addFor, setAddFor] = useState<string | null>(null) // a class opened from "+ Walk-in", with Add ready
  useEffect(() => { if (route.id !== addFor) setAddFor(null) }, [route.id])
  const [chosen, setChosen] = useState<Record<string, string>>({})   // the filters, e.g. { location: "Achrafieh" }
  const [showFilters, setShowFilters] = useState(false)  // the phone's filters, folded behind "Filter"
  // Re-draw every 30 seconds so "Updated 3 min ago" stays true.
  const [, tick] = useState(0)
  useEffect(() => {
    const timer = window.setInterval(() => tick((n) => n + 1), 30_000)
    return () => window.clearInterval(timer)
  }, [])
  const now = new Date()
  const tz = data.timeZone
  const language = safeLanguage(props.language)
  const today = calendarDay(now, tz)
  const attention = needsAttention(data.sessions, data.lastSync, now)
  const urgent = attention.some((a) => a.kind !== "moved")     // anything that needs action, not just telling
  // The badge counts classes; a late sync has its own banner above every section.
  const classItems = attention.filter((a) => a.kind !== "sync").length
  const attentionLabel = `Needs attention, ${classItems} ${classItems === 1 ? "class" : "classes"}`
  const when: When = (iso) => `${dayLabel(calendarDay(new Date(iso), tz), language)} · ${timeOf(new Date(iso), tz)}`

  // Refresh: sync Google Calendar first, then load. The sync takes a few seconds, so look
  // again every 2 seconds until its time changes (up to 20 seconds). If the sync can't be
  // started, it still loads what the database has.
  async function refresh() {
    setRefreshing(true)
    setSlow(false)
    const before = data.lastSync
    let started = true
    try { await call("owner_sync", {}) } catch { started = false }
    let fresh = await reload()
    for (let i = 0; started && fresh && fresh.lastSync === before && i < 10; i++) {
      await new Promise((done) => window.setTimeout(done, 2000))
      fresh = await reload()
    }
    if (started && fresh && fresh.lastSync === before) setSlow(true)
    setRefreshing(false)
  }

  // This week's classes, the rest of the month, and what the search finds: each grouped by day
  const byDay = (list: OwnerSession[]) => {
    const groups: [string, OwnerSession[]][] = []
    for (const s of list) {
      const day = calendarDay(new Date(s.starts_at), tz)
      const group = groups.find(([d]) => d === day)
      if (group) group[1].push(s)
      else groups.push([day, [s]])
    }
    return groups
  }
  const lastDay = addDays(today, BOARD_DAYS - 1)
  const allUpcoming = ownerClasses(data.sessions, now)
  const filters = filterOptions(allUpcoming)
  const upcoming = applyFilters(allUpcoming, chosen)
  const week = byDay(upcoming.filter((s) => calendarDay(new Date(s.starts_at), tz) <= lastDay))
  const later = byDay(upcoming.filter((s) => calendarDay(new Date(s.starts_at), tz) > lastDay))
  const found = query.trim() ? findClasses(upcoming, query, props.countryCode ?? "") : null
  const dayName = (day: string) =>
    day === today ? `Today · ${dayLabel(day, language)}` : day === addDays(today, 1) ? `Tomorrow · ${dayLabel(day, language)}` : dayLabel(day, language)

  // What's open. On a desktop the first class is shown when none is picked.
  const byId = new Map(data.sessions.map((s) => [s.id, s]))
  const firstClass = week[0]?.[1][0]
  const openClass = route.section === "classes"
    ? (route.id ? byId.get(route.id) : look.isDesktop ? firstClass : undefined)
    : undefined
  // On a desktop, Needs attention opens its first item, as Classes opens its first class.
  const firstItem = attention.find((a) => a.kind !== "sync")
  const attentionId = route.id ?? (look.isDesktop && firstItem ? firstItem.session.id : null)
  // Once everyone is ticked as told, the class leaves the list, but stays open until the
  // owner picks something else, so the last tick doesn't make the screen disappear.
  const openSession = route.section === "attention" && attentionId ? byId.get(attentionId) : undefined
  const openItem = route.section === "attention" && attentionId
    ? attention.find((a) => a.kind !== "sync" && a.session.id === attentionId)
      ?? (openSession?.cancelled_at ? { kind: "cancelled" as const, session: openSession }
        : openSession && wasMoved(openSession) ? { kind: "moved" as const, session: openSession } : undefined)
    : undefined

  const pickClass = (id: string) => go({ section: "classes", id })

  // The phone's "Next class" card: today's class under way or next, unless searching or filtering
  const next = !look.isDesktop && !query.trim() && !Object.values(chosen).some(Boolean)
    ? nextClass(data.sessions, now, today, (iso) => calendarDay(new Date(iso), tz))
    : null
  const nextCard = next ? (
    <NextClassCard session={next} look={look} tz={tz} now={now}
      onAdd={() => { setAddFor(next.id); pickClass(next.id) }} onOpen={() => pickClass(next.id)} />
  ) : undefined
  const list = route.section === "classes" ? (
    <ClassesList look={look} query={query} setQuery={setQuery} filters={filters} chosen={chosen} setChosen={setChosen}
      showFilters={showFilters} setShowFilters={setShowFilters} showLater={showLater} setShowLater={setShowLater}
      found={found} week={week} later={later} byDay={byDay} dayName={dayName} tz={tz} selected={openClass?.id} pick={pickClass} nextCard={nextCard} />
  ) :<AttentionList attention={attention} look={look} when={when} selected={attentionId} pick={(id) => go({ section: "attention", id })} />

  const detail = openClass
    ? <ClassDetail key={openClass.id} session={openClass} look={look} when={when} call={call} reload={reload} countryCode={props.countryCode} notify={notify}
      sessions={data.sessions} studio={props.studioName} startAdding={addFor === openClass.id}
      openAttention={(id) => go({ section: "attention", id })} />
    : openItem && openItem.kind !== "sync"
      ? <AttentionDetail key={openItem.session.id} item={openItem} look={look} when={when} call={call} reload={reload}
          sessions={data.sessions} studio={props.studioName} countryCode={props.countryCode} notify={notify} />
      : <p style={{ ...look.muted, marginTop: 8 }}>{route.section === "classes" ? "Pick a class to see who's coming." : "Pick an item to see the details."}</p>

  const sections = (
    <>
      <button className="bd-tab" type="button" onClick={() => go({ section: "classes", id: null })}
        aria-current={route.section === "classes" ? "page" : undefined} style={look.tab(route.section === "classes")}>Classes</button>
      <button className="bd-tab" type="button" onClick={() => go({ section: "attention", id: null })}
        aria-current={route.section === "attention" ? "page" : undefined}
        aria-label={attentionLabel}
        style={look.tab(route.section === "attention")}>
        Needs attention{classItems > 0 && <span style={look.badge(urgent)} aria-hidden="true">{classItems}</span>}
      </button>
    </>
  )
  const syncItem = attention.find((a) => a.kind === "sync")
  const banner = syncItem ? <SyncBanner item={syncItem} look={look} when={when} /> : null
  const refreshButton = (
    <button className="bd-refresh" type="button" onClick={() => void refresh()} disabled={refreshing} title="Sync Google Calendar and reload" style={look.refresh}>
      {refreshing ? <><span className="bd-spinner" aria-hidden="true" />Syncing…</> : "Refresh"}
    </button>
  )
  const updated = (
    <div role="status" style={look.updated}>
      {slow ? "Still syncing — try again in a minute" : `Updated ${ago(loadedAt)}`}
    </div>
  )
  const logOutButton = <button className="bd-logout" type="button" onClick={logOut} style={look.logout}>Log out</button>

  // Screen readers hear the confirmation from a region that's always there; everyone else
  // sees it. Live, it's drawn into the page body, so nothing around it can hide it.
  const toastView = (
    <>
      <div role="status" aria-live="polite" style={look.srOnly}>{toast ? toast.text : ""}</div>
      {toast && (
        <div style={look.toastWrap(!inEditor)}>
          <div className="bd-fade" style={look.toast}>
            <span aria-hidden="true">✓ {toast.text}</span>
            {toast.link && (
              <a className="bd-toast-link" href={toast.link.href} target="_blank" rel="noopener noreferrer"
                onClick={() => setToast(null)} style={look.toastLink}>{toast.link.label}</a>
            )}
          </div>
        </div>
      )}
    </>
  )
  const toastLayer = inEditor ? toastView : createPortal(<div className="bd" style={{ ...props.textFont }}>{toastView}</div>, document.body)

  // ── Desktop: a tinted sidebar fixed to the full height, then the list and the details
  if (look.isDesktop) {
    return (
      <div className="bd-fade" style={look.app}>
        {toastLayer}
        <nav style={look.sidebar}>
          <div style={{ marginBottom: 24 }}>
            <h1 style={{ ...look.title, fontSize: "1.9em" }}>{props.studioName || "Bookings"}</h1>
            <div style={look.muted}>Bookings</div>
          </div>
          {sections}
          <div style={{ flex: 1 }} />
          {refreshButton}
          {updated}
          {logOutButton}
        </nav>
        <div style={{ display: "flex", flexDirection: "column", minHeight: 0, height: "100%" }}>
          {banner}
          <div style={{ ...look.surface, flex: 1, height: "auto" }}>
            <div style={look.listColumn}>{list}</div>
            <div style={look.detailColumn}>{detail}</div>
          </div>
        </div>
      </div>
    )
  }

  // ── Phone: one screen at a time; an open class or item gets its own screen. The
  // sections and Refresh sit in a bar at the bottom, where the thumb reaches; Log out is
  // in a menu at the top, where it's hard to hit by accident.
  const bottomBar = (
    <nav aria-label="Sections" style={look.bottomBar(!inEditor)}>
      <button className="bd-tab" type="button" onClick={() => go({ section: "classes", id: null })}
        aria-current={route.section === "classes" ? "page" : undefined} style={look.barButton(route.section === "classes")}>
        Classes
      </button>
      <button className="bd-tab" type="button" onClick={() => go({ section: "attention", id: null })}
        aria-current={route.section === "attention" ? "page" : undefined}
        aria-label={attentionLabel}
        style={look.barButton(route.section === "attention")}>
        Attention{classItems > 0 && <span style={look.badge(urgent)} aria-hidden="true">{classItems}</span>}
      </button>
      <button className="bd-tab" type="button" onClick={() => void refresh()} disabled={refreshing}
        aria-label={refreshing ? "Syncing" : "Refresh"} title="Sync Google Calendar and reload" style={look.barButton(false)}>
        {refreshing ? <span className="bd-spinner" aria-hidden="true" /> : "Refresh"}
      </button>
    </nav>
  )
  const header = (
    <div style={{ display: "flex", alignItems: "flex-start", gap: 8 }}>
      <div style={{ flex: 1, minWidth: 0 }}>
        <h1 style={look.title}>{props.studioName || "Bookings"}</h1>
        {updated}
      </div>
      <Menu look={look}>{logOutButton}</Menu>
    </div>
  )
  return (
    <div className="bd-fade" style={{ display: "flex", flexDirection: "column", gap: 16, paddingBottom: inEditor ? 0 : 96 }}>
      {route.id && (openClass || openItem) ? (
        <>
          <button className="bd-link" type="button" onClick={() => go({ section: route.section, id: null })}
            style={{ ...look.link, alignSelf: "flex-start", textDecoration: "none", minHeight: 44 }}>‹ Back</button>
          {banner}
          <div style={{ ...look.card, padding: 20 }}>{detail}</div>
        </>
      ) : (
        <>{header}{banner}{list}</>
      )}
      {/* Live: drawn into the page body, so nothing Framer wraps around it stops it from
          staying on screen. It carries the dashboard's class and font with it. */}
      {inEditor ? bottomBar : createPortal(<div className="bd" style={{ ...props.textFont }}>{bottomBar}</div>, document.body)}
      {toastLayer}
    </div>
  )
}

